const b = msg.payload || {};
const obrig = ['segmentoId','consultaId','audioUrl','callbackUrl','callbackToken'];
const faltando = obrig.filter(k => !b[k]);

if (faltando.length > 0) {
    msg.statusCode = 400;
    msg.payload = { aceito: false, motivo: 'PayloadInvalido', campos: faltando };
    return [null, msg];
}

const jobRef = 'nr-' + Date.now() + '-' + b.segmentoId.substring(0, 8);
flow.set('job_' + b.segmentoId, { inicio: Date.now(), jobRef });

const msgResposta = { ...msg, statusCode: 202, payload: { aceito: true, jobRef } };
const msgContinuar = { ...msg, jobRef };

return [msgContinuar, msgResposta];

msg.url = msg.payload.audioUrl;
msg.method = 'GET';
// guarda o payload original do job para as proximas etapas
msg.jobOriginal = msg.payload;
return msg;

const FormData = global.get('FormData') || require('form-data');
const form = new FormData();
form.append('audio_file', msg.payload, {
    filename: 'segmento.webm',
    contentType: (msg.jobOriginal.formato || 'audio/webm')
});

msg.url = (env.get('WHISPER_URL') || 'http://whisper:9000') +
    '/asr?task=transcribe&language=pt&output=json';
msg.method = 'POST';
msg.headers = form.getHeaders();
msg.payload = form;
return msg;

const asr = msg.payload || {};
const job = msg.jobOriginal;

const trechos = (asr.segments || []).map(s => ({
    inicioMs: Math.round((s.start || 0) * 1000),
    fimMs: Math.round((s.end || 0) * 1000),
    texto: (s.text || '').trim()
}));

const confiancas = (asr.segments || [])
    .map(s => (typeof s.avg_logprob === 'number' ? Math.exp(s.avg_logprob) : null))
    .filter(v => v !== null);
const confianca = confiancas.length
    ? Math.round((confiancas.reduce((a, b) => a + b, 0) / confiancas.length) * 100) / 100
    : 0.8;

msg.callbackPayload = {
    segmentoId: job.segmentoId,
    consultaId: job.consultaId,
    status: 'Ok',
    texto: (asr.text || '').trim(),
    confianca,
    idioma: job.idioma || 'pt-BR',
    trechos,
    motor: { nome: 'whisper-asr-webservice', versao: env.get('ASR_MODEL') || 'medium' }
};
msg.callbackUrl = job.callbackUrl;
msg.segmentoId = job.segmentoId;
return msg;

const crypto = global.get('crypto') || require('crypto');
const secret = env.get('STT_SHARED_SECRET') || '';

const token = crypto
    .createHmac('sha256', secret)
    .update(msg.segmentoId)
    .digest('hex');

msg.url = msg.callbackUrl;
msg.method = 'POST';
msg.headers = {
    'Content-Type': 'application/json',
    'X-Vetly-Service-Token': token
};
msg.payload = msg.callbackPayload;
return msg;

node.status({
    fill: msg.statusCode && msg.statusCode < 300 ? 'green' : 'red',
    shape: 'dot',
    text: 'callback ' + (msg.statusCode || '?') + ' - ' + new Date().toLocaleTimeString()
});
return msg;

const job = (msg.jobOriginal) || (msg.payload && msg.payload.jobOriginal) || {};
const origemNo = (msg.error && msg.error.source && msg.error.source.id) || '';

let motivo = 'Timeout';
if (origemNo === 'http-req-download') motivo = 'AudioIlegivel';
else if (origemNo === 'fn-preparar-asr' || origemNo === 'http-req-whisper') motivo = 'MotorIndisponivel';

const segmentoId = job.segmentoId || msg.segmentoId;
const consultaId = job.consultaId || msg.consultaId;
const callbackUrl = job.callbackUrl || msg.callbackUrl;

if (!segmentoId || !callbackUrl) {
    node.warn('Falha sem segmentoId/callbackUrl recuperavel - descartando: ' +
        JSON.stringify(msg.error && msg.error.message));
    return null;
}

msg.callbackPayload = { segmentoId, consultaId, status: 'Falha', motivo };
msg.callbackUrl = callbackUrl;
msg.segmentoId = segmentoId;
node.warn('STT falhou (' + motivo + ') para segmento ' + segmentoId + ': ' +
    (msg.error && msg.error.message));
return msg;
